module benchmark/solution

import std/json (Json, JNull, JBool, JNumber, JString, JArray, JObject, decode, jnum, js)
import std/string (join)
import std/list (map)
import std/math (floatToInt, intToFloat)

pure func setField(fields: [{key: string, value: Json}], k: string, v: Json) -> [{key: string, value: Json}] =
  map(\f. if f.key == k then {key: f.key, value: v} else f, fields)

pure func update(j: Json, k: string, v: Json) -> Json =
  match j {
    JObject(fields) => JObject(setField(fields, k, v)),
    other => other
  }

pure func showNum(n: float) -> string =
  if intToFloat(floatToInt(n)) == n then show(floatToInt(n)) else show(n)

func render(j: Json) -> string =
  match j {
    JNull => "null",
    JBool(b) => if b then "true" else "false",
    JNumber(n) => showNum(n),
    JString(s) => show(s),
    JArray(xs) => "[${join(", ", map(render, xs))}]",
    JObject(fields) => "{${join(", ", map(\f. "${show(f.key)}: ${render(f.value)}", fields))}}"
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(obj) => {
      let updated = update(update(obj, "age", jnum(31.0)), "role", js("senior engineer"));
      println(render(updated))
    },
    Err(e) => println("error: ${e}")
  }
}

