    other => other
  }

pure func showNum(n: float) -> string =
  if intToFloat(floatToInt(n)) == n then show(floatToInt(n)) else show(n)

pure func quote(s: string) -> string =
  "\"${replaceMany(s, [("\\\\", "\\\\\\\\"), ("\\"", "\\\\\\""), ("\\n", "\\\\n")])}\""

func render(j: Json) -> string =
  match j {
    JNull => "null",
    JBool(b) => if b then "true" else "false",
    JNumber(n) => showNum(n),
    JString(s) => quote(s),
    JArray(xs) => "[${join(", ", map(render, xs))}]",
    JObject(fields) => "{${join(", ", map(\f. "${quote(f.key)}: ${render(f.value)}", fields))}}"
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(obj) => {
      let updated = update(update(obj, "age", jnum(31.0)), "role", js("senior engineer"));
      println(render(updated))
    },
    Err(e) => println("error: ${e}")
  }
}
